# make-store-art.ps1 — 5 dil için mağaza görselleri: ikon (512), öne çıkan görsel (1024×500), dikey tanıtım görselleri (1080×1920). Tamamı çizim; oyun içi fotoğraf yok.
Add-Type -AssemblyName System.Drawing
$root = Split-Path $PSScriptRoot -Parent
$out = Join-Path $root 'store\gorseller'
$L = @{
  tr = @{ title='SOKAK KRALI'; tag='AÇIK DÜNYA 3D AKSİYON'; s=@('KOCA ŞEHİR SENİN','62 SİLAH · 8 KATEGORİ','75 KİŞİLİK ÇETENİ KUR','POLİS · SWAT · ORDU','104 PARÇALIK RADYO','KARAKTERİNİ TASARLA'); sub=@('Yürü, araba ve motosiklet sür, yıldız kazan, karteller arasında yüksel','Tabancadan roketatara, yakın dövüşten keskin nişancıya','İsim, renk ve sembol seç; silah dağıt, ittifak kur','5 yıldız, kartel puanı, tanklar ve askerler','8 istasyon: trap, drill, rock, arabesk, techno, lo-fi','Yüz, vücut, saç ve kıyafet dükkânı'); foot='Reklamsız · Satın alma yok · İnternet gerekmez' }
  en = @{ title='STREET KING'; tag='OPEN-WORLD 3D ACTION'; s=@('THE WHOLE CITY IS YOURS','62 WEAPONS · 8 CATEGORIES','BUILD A CREW OF 75','POLICE · SWAT · ARMY','104-TRACK RADIO','DESIGN YOUR CHARACTER'); sub=@('Walk, drive cars and bikes, earn stars, rise among the cartels','From pistols to rocket launchers, melee to sniper','Pick a name, color and symbol; arm them, make alliances','5 stars, cartel score, tanks and soldiers','8 stations: trap, drill, rock, arabesk, techno, lo-fi','Face, body, hair and a clothing shop'); foot='No ads · No purchases · No internet needed' }
  de = @{ title='STRASSENKÖNIG'; tag='OPEN-WORLD-3D-ACTION'; s=@('DIE GANZE STADT GEHÖRT DIR','62 WAFFEN · 8 KATEGORIEN','GANG MIT 75 MANN','POLIZEI · SWAT · ARMEE','RADIO MIT 104 TITELN','GESTALTE DEINEN CHARAKTER'); sub=@('Laufen, Autos und Motorräder fahren, Sterne sammeln, bei den Kartellen aufsteigen','Von Pistole bis Raketenwerfer, Nahkampf bis Scharfschütze','Name, Farbe und Symbol wählen; bewaffnen, Bündnisse schließen','5 Sterne, Kartellpunkte, Panzer und Soldaten','8 Sender: Trap, Drill, Rock, Arabesk, Techno, Lo-Fi','Gesicht, Körper, Haare und Kleiderladen'); foot='Keine Werbung · Keine Käufe · Kein Internet nötig' }
  uk = @{ title='КОРОЛЬ ВУЛИЦЬ'; tag='ВІДКРИТИЙ СВІТ · 3D-ЕКШН'; s=@('УСЕ МІСТО ТВОЄ','62 ВИДИ ЗБРОЇ · 8 КАТЕГОРІЙ','БАНДА З 75 ОСІБ','ПОЛІЦІЯ · SWAT · АРМІЯ','РАДІО ЗІ 104 ТРЕКАМИ','СТВОРИ СВОГО ПЕРСОНАЖА'); sub=@('Ходи, керуй авто й мотоциклами, здобувай зірки, підіймайся серед картелів','Від пістолета до ракетниці, від ножа до снайпера','Обери назву, колір і символ; озброй, укладай союзи','5 зірок, очки картелю, танки та солдати','8 станцій: трап, дрил, рок, арабеск, техно, лоу-фай','Обличчя, тіло, волосся та магазин одягу'); foot='Без реклами · Без покупок · Без інтернету' }
  es = @{ title='REY DE LA CALLE'; tag='ACCIÓN 3D EN MUNDO ABIERTO'; s=@('TODA LA CIUDAD ES TUYA','62 ARMAS · 8 CATEGORÍAS','CREA UNA BANDA DE 75','POLICÍA · SWAT · EJÉRCITO','RADIO CON 104 TEMAS','DISEÑA TU PERSONAJE'); sub=@('Camina, conduce coches y motos, gana estrellas, asciende entre los cárteles','De pistolas a lanzacohetes, cuerpo a cuerpo y francotirador','Elige nombre, color y símbolo; ármalos, haz alianzas','5 estrellas, puntos de cártel, tanques y soldados','8 emisoras: trap, drill, rock, arabesk, techno, lo-fi','Cara, cuerpo, pelo y tienda de ropa'); foot='Sin anuncios · Sin compras · Sin internet' }
}
$GOLD=[System.Drawing.Color]::FromArgb(255,255,210,59); $INK=[System.Drawing.Color]::FromArgb(255,11,13,16); $FG=[System.Drawing.Color]::FromArgb(255,242,239,230); $MUTED=[System.Drawing.Color]::FromArgb(255,190,185,170); $CYAN=[System.Drawing.Color]::FromArgb(255,26,200,255); $RED=[System.Drawing.Color]::FromArgb(255,255,59,59)
function B($c){ New-Object System.Drawing.SolidBrush $c }
function F($name,$size,$bold){ $st = if($bold){[System.Drawing.FontStyle]::Bold}else{[System.Drawing.FontStyle]::Regular}; New-Object System.Drawing.Font $name,([float]$size),$st,([System.Drawing.GraphicsUnit]::Pixel) }
function NewG($w,$h){ $bmp=New-Object System.Drawing.Bitmap $w,$h; $g=[System.Drawing.Graphics]::FromImage($bmp); $g.SmoothingMode='AntiAlias'; $g.TextRenderingHint='AntiAliasGridFit'; $g.InterpolationMode='HighQualityBicubic'; ,@($bmp,$g) }
function Bg($g,$w,$h,$ang){ $r=New-Object System.Drawing.Rectangle 0,0,$w,$h; $br=New-Object System.Drawing.Drawing2D.LinearGradientBrush $r,([System.Drawing.Color]::FromArgb(255,26,30,42)),$INK,([float]$ang); $g.FillRectangle($br,$r); $glow=New-Object System.Drawing.Drawing2D.GraphicsPath; $glow.AddEllipse([float]($w*0.1),[float](-$h*0.1),[float]($w*0.8),[float]($h*0.5)); $pb=New-Object System.Drawing.Drawing2D.PathGradientBrush $glow; $pb.CenterColor=[System.Drawing.Color]::FromArgb(70,255,210,59); $pb.SurroundColors=@([System.Drawing.Color]::FromArgb(0,255,210,59)); $g.FillPath($pb,$glow) }
function Crown($g,$x,$y,$s,$br){ $pts=@((New-Object System.Drawing.PointF ($x+$s*0.14),($y+$s*0.66)),(New-Object System.Drawing.PointF ($x+$s*0.14),($y+$s*0.30)),(New-Object System.Drawing.PointF ($x+$s*0.34),($y+$s*0.48)),(New-Object System.Drawing.PointF ($x+$s*0.50),($y+$s*0.18)),(New-Object System.Drawing.PointF ($x+$s*0.66),($y+$s*0.48)),(New-Object System.Drawing.PointF ($x+$s*0.86),($y+$s*0.30)),(New-Object System.Drawing.PointF ($x+$s*0.86),($y+$s*0.66))); $g.FillPolygon($br,$pts); $g.FillRectangle($br,[float]($x+$s*0.14),[float]($y+$s*0.69),[float]($s*0.72),[float]($s*0.10)); foreach($k in 0.34,0.50,0.66){ $g.FillEllipse((B $RED),[float]($x+$s*$k-$s*0.035),[float]($y+$s*0.71),[float]($s*0.07),[float]($s*0.07)) } }
function Skyline($g,$w,$y0,$h,$seed,$dark){ $rnd=New-Object System.Random $seed; $x=-20; while($x -lt $w){ $bw=40+$rnd.Next(0,70); $bh=[int]($h*0.35)+$rnd.Next(0,[int]($h*0.65)); $g.FillRectangle((B $dark),$x,$y0+$h-$bh,$bw,$bh); $win=B ([System.Drawing.Color]::FromArgb(255,255,210,59)); $win2=B ([System.Drawing.Color]::FromArgb(255,26,200,255)); for($yy=$y0+$h-$bh+14; $yy -lt $y0+$h-12; $yy+=20){ for($xx=$x+8; $xx -lt $x+$bw-8; $xx+=16){ $r=$rnd.Next(0,5); if($r -eq 0){ $g.FillRectangle($win,$xx,$yy,8,11) } elseif($r -eq 1){ $g.FillRectangle($win2,$xx,$yy,8,11) } } }; $x+=$bw+10 } }
function Road($g,$w,$y,$h){ $g.FillRectangle((B ([System.Drawing.Color]::FromArgb(255,28,28,32))),0,$y,$w,$h); $g.FillRectangle((B ([System.Drawing.Color]::FromArgb(255,120,120,128))),0,$y,$w,10); for($x=0;$x -lt $w;$x+=90){ $g.FillRectangle((B $GOLD),$x,$y+$h/2-5,50,10) } }
function Person($g,$x,$y,$s,$shirt,$pants,$skin){ $g.FillEllipse((B $skin),[float]($x-$s*0.14),[float]$y,[float]($s*0.28),[float]($s*0.28)); $g.FillRectangle((B $shirt),[float]($x-$s*0.2),[float]($y+$s*0.3),[float]($s*0.4),[float]($s*0.5)); $g.FillRectangle((B $shirt),[float]($x-$s*0.32),[float]($y+$s*0.32),[float]($s*0.1),[float]($s*0.42)); $g.FillRectangle((B $shirt),[float]($x+$s*0.22),[float]($y+$s*0.32),[float]($s*0.1),[float]($s*0.42)); $g.FillRectangle((B $pants),[float]($x-$s*0.18),[float]($y+$s*0.8),[float]($s*0.16),[float]($s*0.5)); $g.FillRectangle((B $pants),[float]($x+$s*0.02),[float]($y+$s*0.8),[float]($s*0.16),[float]($s*0.5)) }
function Car($g,$x,$y,$w,$col){ $h=$w*0.32; $g.FillRectangle((B $col),[float]$x,[float]($y+$h*0.45),[float]$w,[float]($h*0.55)); $g.FillRectangle((B $col),[float]($x+$w*0.22),[float]$y,[float]($w*0.5),[float]($h*0.5)); $g.FillRectangle((B ([System.Drawing.Color]::FromArgb(200,120,200,255))),[float]($x+$w*0.26),[float]($y+$h*0.08),[float]($w*0.42),[float]($h*0.36)); foreach($k in 0.18,0.78){ $g.FillEllipse((B ([System.Drawing.Color]::FromArgb(255,20,20,20))),[float]($x+$w*$k-$w*0.1),[float]($y+$h*0.75),[float]($w*0.2),[float]($w*0.2)); $g.FillEllipse((B ([System.Drawing.Color]::FromArgb(255,150,150,150))),[float]($x+$w*$k-$w*0.05),[float]($y+$h*0.75+$w*0.05),[float]($w*0.1),[float]($w*0.1)) }; $g.FillRectangle((B $GOLD),[float]($x+$w*0.9),[float]($y+$h*0.55),[float]($w*0.08),[float]($h*0.14)) }
function Gun($g,$x,$y,$s,$col){ $g.FillRectangle((B $col),[float]$x,[float]$y,[float]($s*1.0),[float]($s*0.22)); $g.FillRectangle((B $col),[float]($x+$s*0.2),[float]($y+$s*0.2),[float]($s*0.18),[float]($s*0.42)); $g.FillRectangle((B $col),[float]($x+$s*0.42),[float]($y+$s*0.2),[float]($s*0.08),[float]($s*0.25)); $g.FillRectangle((B $col),[float]($x+$s*0.55),[float]($y+$s*0.2),[float]($s*0.12),[float]($s*0.55)); $g.FillRectangle((B $col),[float]($x-$s*0.3),[float]($y+$s*0.02),[float]($s*0.32),[float]($s*0.18)) }
function Rifle($g,$x,$y,$s,$col){ $g.FillRectangle((B $col),[float]$x,[float]$y,[float]($s*1.6),[float]($s*0.16)); $g.FillRectangle((B $col),[float]($x+$s*1.6),[float]($y+$s*0.03),[float]($s*0.9),[float]($s*0.08)); $g.FillRectangle((B $col),[float]($x+$s*0.5),[float]($y+$s*0.15),[float]($s*0.16),[float]($s*0.4)); $g.FillRectangle((B $col),[float]($x+$s*0.95),[float]($y+$s*0.15),[float]($s*0.14),[float]($s*0.5)); $g.FillRectangle((B $col),[float]($x-$s*0.5),[float]($y-$s*0.02),[float]($s*0.52),[float]($s*0.3)); $g.FillRectangle((B $col),[float]($x+$s*0.4),[float]($y-$s*0.12),[float]($s*0.06),[float]($s*0.12)) }
function Eq($g,$x,$y,$w,$h,$n,$seed){ $rnd=New-Object System.Random $seed; $bw=$w/$n; for($i=0;$i -lt $n;$i++){ $bh=[int]($h*(0.2+0.8*[Math]::Abs([Math]::Sin($i*0.7+$seed)))); $c=if($i%3 -eq 0){$CYAN}else{$GOLD}; $g.FillRectangle((B $c),[float]($x+$i*$bw+3),[float]($y+$h-$bh),[float]($bw-6),[float]$bh) } }
function Stars($g,$x,$y,$n,$s){ $f=F 'Segoe UI Symbol' $s $true; for($i=0;$i -lt 5;$i++){ $c=if($i -lt $n){$GOLD}else{[System.Drawing.Color]::FromArgb(60,255,255,255)}; $g.DrawString([string][char]0x2605,$f,(B $c),[float]($x+$i*$s*1.05),[float]$y) } }
function TextC($g,$t,$font,$col,$cx,$y){ $sz=$g.MeasureString($t,$font); $g.DrawString($t,$font,(B $col),[float]($cx-$sz.Width/2),[float]$y) }
function FitFont($g,$t,$maxW,$start,$name){ $s=$start; while($s -gt 20){ $f=F $name $s $true; if($g.MeasureString($t,$f).Width -le $maxW){ return $f }; $s-=4 }; return (F $name 20 $true) }
function Save($bmp,$path){ $dir=Split-Path $path -Parent; if(-not (Test-Path $dir)){ New-Item -ItemType Directory -Force $dir | Out-Null }; $bmp.Save($path,[System.Drawing.Imaging.ImageFormat]::Png); $bmp.Dispose() }

foreach($lang in $L.Keys){
  $T=$L[$lang]; $d=Join-Path $out $lang
  # --- ikon 512: taç + dil başlığı
  $r=NewG 512 512; $bmp=$r[0]; $g=$r[1]; Bg $g 512 512 60; Crown $g 96 70 320 (B $GOLD)
  $f=FitFont $g $T.title 470 70 'Impact'; TextC $g $T.title $f $FG 256 (380)
  $g.Dispose(); Save $bmp (Join-Path $d 'icon-512.png')
  # --- öne çıkan görsel 1024×500
  $r=NewG 1024 500; $bmp=$r[0]; $g=$r[1]; Bg $g 1024 500 35; Skyline $g 1024 180 320 7 ([System.Drawing.Color]::FromArgb(255,14,16,22)); Road $g 1024 440 60
  Car $g 700 350 220 $RED; Crown $g 60 40 200 (B $GOLD)
  $f=FitFont $g $T.title 680 96 'Impact'; $g.DrawString($T.title,$f,(B $GOLD),300,60); $g.DrawString($T.tag,(F 'Segoe UI' 30 $true),(B $FG),305,180)
  $g.DrawString($T.foot,(F 'Segoe UI' 22 $false),(B $MUTED),305,225)
  $g.Dispose(); Save $bmp (Join-Path $d 'feature-graphic.png')
  # --- dikey tanıtım görselleri 1080×1920
  for($i=0;$i -lt 6;$i++){
    $r=NewG 1080 1920; $bmp=$r[0]; $g=$r[1]; Bg $g 1080 1920 80
    # üst: başlık
    Crown $g 440 70 200 (B $GOLD)
    $f=FitFont $g $T.title 1000 120 'Impact'; TextC $g $T.title $f $GOLD 540 270
    TextC $g $T.tag (F 'Segoe UI' 34 $true) $FG 540 410
    # orta: sahne
    switch($i){
      0 { Skyline $g 1080 560 700 11 ([System.Drawing.Color]::FromArgb(255,14,16,22)); Road $g 1080 1240 140; Car $g 120 1130 420 $CYAN; Car $g 640 1160 320 $RED; Person $g 980 1030 120 $GOLD ([System.Drawing.Color]::FromArgb(255,40,40,60)) ([System.Drawing.Color]::FromArgb(255,224,176,144)); Stars $g 330 1420 3 70 }
      1 { $g.FillRectangle((B ([System.Drawing.Color]::FromArgb(40,255,255,255))),80,560,920,900); Gun $g 200 640 260 $FG; Rifle $g 180 900 300 $FG; Gun $g 560 1120 300 $GOLD; Rifle $g 180 1280 320 $CYAN; $g.DrawString('62',(F 'Impact' 260 $true),(B $GOLD),640,560) }
      2 { Skyline $g 1080 560 520 23 ([System.Drawing.Color]::FromArgb(255,14,16,22)); $g.FillRectangle((B ([System.Drawing.Color]::FromArgb(255,70,70,76))),0,1080,1080,400); $cols=@([System.Drawing.Color]::FromArgb(255,41,128,185),[System.Drawing.Color]::FromArgb(255,41,128,185),$GOLD,[System.Drawing.Color]::FromArgb(255,41,128,185),[System.Drawing.Color]::FromArgb(255,41,128,185)); for($k=0;$k -lt 5;$k++){ Person $g (170+$k*185) (1050-($(if($k -eq 2){80}else{0}))) ($(if($k -eq 2){230}else{190})) $cols[$k] ([System.Drawing.Color]::FromArgb(255,30,30,40)) ([System.Drawing.Color]::FromArgb(255,224,176,144)) }; Crown $g 500 940 80 (B $GOLD) }
      3 { Skyline $g 1080 560 520 5 ([System.Drawing.Color]::FromArgb(255,14,16,22)); Road $g 1080 1080 120; Car $g 80 980 360 ([System.Drawing.Color]::FromArgb(255,240,240,240)); $g.FillRectangle((B $RED),170,970,60,22); $g.FillRectangle((B $CYAN),240,970,60,22); Car $g 600 1000 380 ([System.Drawing.Color]::FromArgb(255,30,30,30)); Stars $g 300 1250 5 90; Person $g 540 760 150 ([System.Drawing.Color]::FromArgb(255,21,24,28)) ([System.Drawing.Color]::FromArgb(255,16,18,22)) ([System.Drawing.Color]::FromArgb(255,224,176,144)) }
      5 { Person $g 540 620 460 $GOLD ([System.Drawing.Color]::FromArgb(255,43,47,74)) ([System.Drawing.Color]::FromArgb(255,224,176,144)); $g.FillEllipse((B ([System.Drawing.Color]::FromArgb(255,42,26,14))),[float](540-460*0.15),[float](612),[float](460*0.30),[float](460*0.16)); $g.FillRectangle((B ([System.Drawing.Color]::FromArgb(255,17,17,17))),[float](540-460*0.14),[float](690),[float](460*0.28),[float](22)); $sw=@($GOLD,$RED,$CYAN,[System.Drawing.Color]::FromArgb(255,155,89,182),[System.Drawing.Color]::FromArgb(255,46,204,113),[System.Drawing.Color]::FromArgb(255,241,241,241),[System.Drawing.Color]::FromArgb(255,20,20,20)); $g.FillRectangle((B ([System.Drawing.Color]::FromArgb(60,255,255,255))),100,1340,880,170); for($k=0;$k -lt 7;$k++){ $g.FillEllipse((B $sw[$k]),[float](130+$k*120),[float](1380),[float](90),[float](90)) } }
      4 { Eq $g 120 700 840 520 14 3; $g.DrawString([string][char]0x266A,(F 'Segoe UI Symbol' 260 $true),(B $FG),380,1180); $g.DrawString('104',(F 'Impact' 200 $true),(B $GOLD),120,560) }
    }
    # alt: özellik başlığı ve açıklama
    $g.FillRectangle((B ([System.Drawing.Color]::FromArgb(230,8,10,14))),0,1540,1080,380)
    $g.FillRectangle((B $GOLD),0,1540,1080,6)
    $ft=FitFont $g $T.s[$i] 1000 72 'Impact'; TextC $g $T.s[$i] $ft $FG 540 1590
    $fs=F 'Segoe UI' 34 $false; $txt=$T.sub[$i]; $rect=New-Object System.Drawing.RectangleF 60,1700,960,150; $fmt=New-Object System.Drawing.StringFormat; $fmt.Alignment='Center'; $g.DrawString($txt,$fs,(B $MUTED),$rect,$fmt)
    $g.DrawString($T.foot,(F 'Segoe UI' 24 $false),(B ([System.Drawing.Color]::FromArgb(255,120,115,100))),(New-Object System.Drawing.RectangleF 60,1850,960,50),$fmt)
    $g.Dispose(); Save $bmp (Join-Path $d ("promo-"+($i+1)+".png"))
  }
  Write-Host "$lang hazır"
}
Get-ChildItem $out -Recurse -File | Select-Object @{n='file';e={$_.FullName.Replace($out+'\','')}}, Length
